/bin/sh -lc "cd /work && python3 -c \"
import openpyxl
from collections import Counter
wb = openpyxl.load_workbook('camp_register.xlsx')
ws = wb['Camp Register']
camp = None
counts, total = Counter(), Counter()
for row in ws.iter_rows(values_only=True):
    first = row[0]
    if isinstance(first, str):
        if 'camp' in first.lower():
            camp = first.strip()
        continue  # header row
    if isinstance(first, int) and camp:
        total[camp] += 1
        if str(row[3]).strip().upper() == 'F':
            counts[camp] += 1
for camp in sorted(counts, key=lambda c: -counts[c]):
    print(f'{camp}: women={counts[camp]}, total={total[camp]}')
\""

